public void setOPIInput(final IEditorInput input, final boolean persist) throws PartInitException
{
    if (debug)
    {
        final IViewSite view = getViewSite();
        System.out.println(view.getId() + ":" + view.getSecondaryId() + " displays " + input.getName());
    }
    this.input = input;
    setTitleToolTip(input.getToolTipText());
    opiRuntimeDelegate.init(site, input);
    if (persist) {
        IMemento memento = createMemento();
        saveMemento(memento);
    }
}

private IMemento createMemento() {
    StringWriter writer = new StringWriter();
    try {
        return XMLMemento.createWriteRoot(writer);
    } catch (WorkbenchException e) {
        OPIBuilderPlugin.getLogger().log(Level.WARNING, "Failed to create memento", e);
        return null;
    }
}

private void saveMemento(IMemento memento) {
    if (memento!= null) {
        memento.putString(TAG_FACTORY_ID, opiRuntimeDelegate.getFactoryID());
        IMemento inputMem = memento.createChild(TAG_INPUT);
        inputMem.putString("path", input.getAdapter(String.class));
        inputMem.putString("macros", opiRuntimeDelegate.getMacros());
        saveMemento(memento, site);
    }
}

private void saveMemento(IMemento memento, IViewSite site) {
    MPlaceholder placeholder = findPlaceholder();
    if (placeholder!= null) {
        placeholder.getPersistedState().put(TAG_MEMENTO, memento.toString());
    }
}

