public static void gqgenerategausslegendre(int n, ref int info, ref double[] x, ref double[] w)
{
    int i = 0;
    double[] d = new double[0];
    double[] e = new double[0];
    double[,] z = new double[0,0];
    info = 0;
    x = new double[0];
    w = new double[0];
    if( n<1 )
    {
        info = -1;
        return;
    }
    info = 1;

    //
    // Initialize
    //
    d = new double[n];
    e = new double[n];
    for(i=1; i<=n-1; i++)
    {
        d[i-1] = 0;
        e[i-1] = 0;
    }
    d[n-1] = 0;

    //
    // EVD
    //
    if(!evd.smatrixtdevd(ref d, e, n, 3, ref z) )
    {
        info = -3;
        return;
    }

    //
    // Generate
    //
    x = new double[n];
    w = new double[n];
    for(i=1; i<=n; i++)
    {
        x[i-1] = z[0,i-1];
        w[i-1] = math.sqr(z[0,i-1]);
    }
}

