BigInteger sqrt() 
{
    uint numBits = (uint)this.bitCount();
    if((numBits & 0x1)!= 0)        // odd number of bits
    {
        numBits--;
        uint mask = 0x01;
        for(int i = 0; i < 32; i++)
        {
            if((numBits & mask)!= 0)
            {
                numBits = (uint)(numBits - mask);
                break;
            }
            mask <<= 1;
        }
    }
    uint mask = 0x01;
    for(int i = 0; i < 32; i++)
    {
        if((numBits & mask)!= 0)
        {
            numBits = (uint)(numBits - mask);
            break;
        }
        mask <<= 1;
    }
    BigInteger result = new BigInteger();
    result.data[0] = (uint)(numBits >> 5);
    result.dataLength = 1;
    return result;
}

