protected static int[] getAllowedIfdsFromInfo(int info) {
    int ifdFlags = getAllowedIfdFlagsFromInfo(info);
    int[] ifds = IfdData.getIfds();
    int[] allowedIfds = new int[ifds.length];
    int counter = 0;
    for (int i : ifds) {
        if ((ifdFlags & (1 << i))!= 0) {
            allowedIfds[counter++] = i;
        }
    }
    if (counter == 0) {
        return null;
    }
    return Arrays.copyOfRange(allowedIfds, 0, counter);
}

