def _expandvars(fname):
    i = 0
    while True:
        m = re.search(r'\$\((\w+)\)', fname[i:])
        if not m:
            break
        i, j = m.span(0)
        name = m.group(1)
        if name in os.environ:
            tail = fname[j:]
            fname = fname[:i] + os.environ[name]
            i = len(fname)
            fname += tail
        else:
            i = j
    return fname

