private static void AssignMediaEncoderSettingsProperty(IGallerySettings gallerySetting, PropertyInfo property, string[] mediaEncodings)
{
    IMediaEncoderSettingsCollection mediaEncoderSettings = (IMediaEncoderSettingsCollection)property.GetValue(gallerySetting, null);
    int seq = 0;
    foreach (string mediaEncStr in mediaEncodings)
    {
        // Each string item is double-pipe-delimited. Ex: ".avi||.mp4||-i {SourceFilePath} {DestinationFilePath}"
        string[] mediaEncoderItems = mediaEncStr.Split(new[] { "||" }, StringSplitOptions.None);
        if (mediaEncoderItems.Length!= 3)
        {
            throw new ArgumentOutOfRangeException(String.Format(CultureInfo.CurrentCulture, "GallerySetting.RetrieveGallerySettingsFromDataStore cannot parse the media encoder settings for property {0}. Encountered invalid string: '{1}'", property.Name, mediaEncStr));
        }
        string[] fileTypes = mediaEncoderItems[0].Split(new char[] { '.' }, StringSplitOptions.RemoveEmptyEntries);
        string[] fileExtensions = new string[fileTypes.Length];
        for (int i = 0; i < fileTypes.Length; i++)
        {
            fileExtensions[i] = "." + fileTypes[i];
        }
        string command = mediaEncoderItems[1];
        string[] parameters = mediaEncoderItems[2].Split(new char[] {'' }, StringSplitOptions.RemoveEmptyEntries);
        mediaEncoderSettings.Add(new MediaEncoderSettings(seq, fileExtensions, command, parameters));
        seq += 1;
    }
    mediaEncoderSettings.Validate();
}

