    for child in xml.childNodes:
        # regular text node -> just copy
        if child.nodeType == child.TEXT_NODE:
            skeleton += child.nodeValue
        # xml tag -> try to expand value of test.tag.show()
        elif child.nodeType == child.ELEMENT_NODE:
            try:
                name = child.tagName
                # some variables need a special treatment
                if name == "test":
                    value = test.fullPath()
                elif name == "bugs":
                    value = test.testname.bugs.show()
                elif name == "reproducers":
                    value = test.testname.bugs.reproducers.show()
                elif name == "runfor":
                    value =''.join(test.runfor.data)
                elif name == "requires":
                    value =''.join(test.requires.data)
                elif name == "rhtsrequires":
                    value =''.join(test.rhtsrequires.data)
                elif name == "package":
                    value = test.package.show()
                elif name == "type":
                    value = test.type.show()
                elif name == "path":
                    value = test.path.show()
                elif name == "name":
                    value = test.testname.show()
                elif name == "author":
                    value = test.author.show()
                elif name == "email":
                    value = test.email.show()
                elif name == "license":
                    value = test.license.show()
                elif name == "description":
                    value = test.description.show()
                elif name == "time":
                    value = test.time.show()
                elif name == "priority":
                    value = test.priority.show()
                elif name == "confidential":
                    value = test.confidential.show()
                elif name == "destructive":
                    value = test.destructive.show()
                elif name == "prefix":
                    value = test.prefix.show()
                elif name == "skeleton":
                    value = test.skeleton.show()
                # replace the tag with the value
                skeleton += "<" + name + ">" + value + "</" + name + ">"
            except:
                # if the tag is not found, just copy the text
                skeleton += child.toxml()
    return skeleton
